#include <assert.h>
#include <stdio.h>
#include "../firmware/proto/groovebox.h"
int main(void){groovebox_t g;groovebox_init(&g,120u);groovebox_set_external_clock(&g,1u);g.acid_seq[0].step[0].note=36u;g.acid_seq[0].step[0].flags=SEQ16_GATE|SEQ16_ACCENT;groovebox_set_drum_step(&g,0u,0u,1u<<DRUM_BD,1u<<DRUM_BD);groovebox_set_drum_step(&g,1u,0u,1u<<DRUM_SD,0u);g.patterns.acid[0][3][0].note=55u;g.patterns.acid[0][3][0].flags=SEQ16_GATE;g.patterns.drum_hits[1][3][4]=(uint16_t)(1u<<DRUM_CH);assert(song_append(&g.song,3u,1u));assert(groovebox_feed_midi_realtime(&g,0xFAu)&MT_EVT_START);for(int i=0;i<6;i++)(void)groovebox_feed_midi_realtime(&g,0xF8u);assert(g.step==1u);int heard=0;for(int i=0;i<4096;i++){int16_t l=0,r=0;groovebox_process(&g,&l,&r);if(l||r)heard=1;}assert(heard);uint8_t blob[4096];size_t n=0;g.mixer.track[2].pan=-12000;assert(groovebox_save(&g,blob,sizeof(blob),&n)==PROJECT_OK);assert(n>2000u);groovebox_t copy;assert(groovebox_load(&copy,blob,n)==PROJECT_OK);assert(copy.transport.bpm==120u);assert(copy.acid_seq[0].step[0].note==36u);assert(copy.drum_hits[0][0]&(1u<<DRUM_BD));assert(copy.mixer.track[2].pan==-12000);assert(copy.song.length==1u&&copy.song.slot[0].pattern==3u);assert(copy.patterns.acid[0][3][0].note==55u);assert(copy.patterns.drum_hits[1][3][4]&(1u<<DRUM_CH));puts("groovebox integration tests: ok");return 0;}
